<script setup>
import { computed, ref } from 'vue'
import { RouterLink } from 'vue-router'
const props = defineProps({ filas: { type: Array, required: true } })
const criterio = ref('puntos')
const ordenadas = computed(() => [...props.filas].sort((a, b) => b[criterio.value] - a[criterio.value] || b.puntos - a.puntos || b.diferencia - a.diferencia || a.nombre.localeCompare(b.nombre, 'es')))
</script>
<template>
  <section class="panel ranking-panel"><div class="section-head"><h2>Clasificación de equipos</h2><div class="ranking-sort"><label for="criterio-ranking">Ordenar por</label><select id="criterio-ranking" v-model="criterio"><option value="puntos">Puntos</option><option value="victorias">Victorias</option></select></div></div><div class="table-wrap"><table class="data-table"><caption class="sr-only">Clasificación ordenada por {{ criterio }}. Victoria: 3 puntos. Empate: 1 punto. Derrota: 0 puntos.</caption><thead><tr><th scope="col">Pos.</th><th scope="col">Equipo</th><th scope="col"><abbr title="Partidos jugados">PJ</abbr></th><th scope="col"><abbr title="Victorias">V</abbr></th><th scope="col"><abbr title="Empates">E</abbr></th><th scope="col"><abbr title="Derrotas">D</abbr></th><th scope="col"><abbr title="Puntaje a favor">PF</abbr></th><th scope="col"><abbr title="Puntaje en contra">PC</abbr></th><th scope="col"><abbr title="Diferencia de puntaje">DIF</abbr></th><th scope="col">Puntos</th></tr></thead><tbody><tr v-for="(fila, index) in ordenadas" :key="fila.equipoId" :class="{ 'ranking-leader': index === 0 }"><td><span class="position" :class="{ 'position-first': index === 0 }">{{ index + 1 }}</span></td><th scope="row"><RouterLink :to="`/equipos/${fila.equipoId}`">{{ fila.nombre }}</RouterLink></th><td>{{ fila.jugados }}</td><td>{{ fila.victorias }}</td><td>{{ fila.empates }}</td><td>{{ fila.derrotas }}</td><td>{{ fila.aFavor }}</td><td>{{ fila.enContra }}</td><td>{{ fila.diferencia > 0 ? '+' : '' }}{{ fila.diferencia }}</td><td class="ranking-points">{{ fila.puntos }}</td></tr></tbody></table></div><p class="ranking-note">Clasificación oficial: puntos, diferencia de puntaje y nombre del equipo. El orden por victorias es una vista alternativa.</p></section>
</template>
<style scoped>.ranking-panel{padding-bottom:1rem}.ranking-sort{display:flex;align-items:center;gap:.75rem}.ranking-sort label{font-size:.875rem;color:#a0a5b9;white-space:nowrap}.ranking-sort select{min-width:130px;min-height:40px;padding:.5rem 2rem .5rem .7rem}.data-table th[scope=row]{font-size:.95rem;text-align:left;font-weight:600}.data-table th[scope=row] a{color:#dedbea}.data-table td:not(:first-child),.data-table thead th:not(:nth-child(2)){text-align:center}.ranking-leader{background:#29233855}.ranking-points{font-weight:700;color:#abebd2;font-size:1.1rem}.position{width:28px;height:28px;display:inline-grid;place-items:center;border-radius:5px;color:#9ea6bd}.position-first{background:#493c60;color:#e0cfff;font-weight:700}.ranking-note{font-size:.78rem;color:#939cb5;margin:1.3rem 0 0;line-height:1.5}abbr{cursor:help;text-decoration:none}@media(max-width:550px){.section-head{align-items:flex-start;flex-direction:column}.ranking-sort{width:100%;justify-content:space-between}.data-table th,.data-table td{padding:.85rem .7rem}}</style>
